	@Test
	void graphTailMemoUsesItsLexicalFrameAndRetainsDuplicateRows() throws Exception {
		Fixture fixture = new Fixture();
		fixture.baseline();
		LmdbNativeFactorizedRows factorized = fixture.factorized(fixture.graph);
		assertThat(factorized).as("repeatable GRAPH with an exact read frame must admit a bounded enum tail")
				.isNotNull();
		LmdbNativeFactorizedRows.TailBranch branch = factorized.branches[0];
		try {
			for (int pass = 0; pass < 3; pass++) {
				var result = branch.result(fixture.row, factorized);
				assertThat(result.count).isEqualTo(3L);
				assertThat(result.values).startsWith(210L, 210L, 211L);
			}
			assertThat(fixture.opens.get()).as("first observation, promotion, then bounded replay").isEqualTo(2);
			fixture.row.rollback(fixture.frameMark);
			assertThat(fixture.row.bind(1, 31L)).isTrue();
			var second = branch.result(fixture.row, factorized);
			assertThat(second.values).startsWith(310L, 310L, 311L);
			assertThat(fixture.opens.get()).isEqualTo(3);
			assertThat(fixture.closes.get()).isEqualTo(3);
			assertThat(fixture.row.slots[2]).isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
		} finally {
			branch.close();
			branch.close();
		}
		assertReleased(factorized);
	}

